window.QBANK = window.QBANK || {};
window.QBANK["sd-bahasa-inggris"] = {
  level: "SD", subject: "Bahasa Inggris", duration: 900,
  questions: [
    { q: "What do you say to greet someone in the morning?", options: ["Good night", "Good morning", "Good evening", "Good bye"], answer: 1, solution: "1. 'Good morning' artinya 'selamat pagi'. 2. Diucapkan saat bertemu orang pada pagi hari. 3. 'Good night' artinya selamat malam, 'good evening' selamat sore." },
    { q: "She ___ to school every day.", options: ["go", "goes", "going", "went"], answer: 1, solution: "1. Ini kalimat simple present dengan subjek 'she' (orang ketiga tunggal). 2. Aturannya: kata kerja ditambah -s atau -es, jadi 'go' menjadi 'goes'. 3. Kalimat lengkapnya: 'She goes to school every day.'" },
    { q: "What animal says 'meow'?", options: ["Dog", "Cat", "Bird", "Fish"], answer: 1, solution: "1. 'Meow' adalah bunyi khas hewan ini. 2. 'Cat' artinya kucing, dan kucing bersuara 'meow'. 3. Anjing menggonggong ('bark'), burung berkicau." },
    { q: "How many days are there in a week?", options: ["Five", "Six", "Seven", "Eight"], answer: 2, solution: "1. 'Week' artinya satu minggu atau sepekan. 2. Nama-nama harinya: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday. 3. Jumlahnya ada 7, dalam bahasa Inggris 'seven'." },
    { q: "I ___ a student.", options: ["am", "is", "are", "be"], answer: 0, solution: "1. Subjek kalimatnya adalah 'I' yang artinya 'saya'. 2. Pasangan to be untuk 'I' adalah 'am'. 3. 'Is' untuk he/she/it, sedangkan 'are' untuk you/we/they." },
    { q: "The sky is ___.", options: ["green", "blue", "red", "yellow"], answer: 1, solution: "1. 'Sky' artinya langit. 2. Pada siang hari langit terlihat berwarna biru. 3. Biru dalam bahasa Inggris adalah 'blue'." },
    { q: "One book, two ___.", options: ["book", "bookes", "books", "book's"], answer: 2, solution: "1. Ini tentang bentuk jamak (plural) kata benda. 2. Aturan umumnya: tambah -s di akhir kata, jadi 'book' menjadi 'books'. 3. 'Bookes' salah eja, sedangkan 'book's' artinya 'milik buku'." },
    { q: "___ is my mother. She is kind.", options: ["He", "She", "It", "They"], answer: 1, solution: "1. 'Mother' artinya ibu, yaitu perempuan. 2. Kata ganti untuk perempuan tunggal adalah 'she'. 3. 'He' untuk laki-laki, 'they' untuk banyak orang." },
    { q: "They ___ like milk.", options: ["doesn't", "don't", "isn't", "not"], answer: 1, solution: "1. Ini kalimat negatif dalam simple present. 2. Subjek 'they' (jamak) memakai 'don't'. 3. 'Doesn't' hanya dipakai untuk subjek he, she, atau it." },
    { q: "My father's father is my ___.", options: ["uncle", "grandfather", "brother", "cousin"], answer: 1, solution: "1. 'Father's father' artinya ayah dari ayahku. 2. Ayah dari ayah disebut kakek. 3. Kakek dalam bahasa Inggris adalah 'grandfather'. 'Uncle' artinya paman, 'cousin' artinya sepupu." },
    { q: "Someone says 'Good afternoon!' to you. What do you answer?", options: ["Good night", "Good afternoon", "Good bye", "See you"], answer: 1, solution: "1. Sapaan dibalas dengan sapaan yang sama. 2. 'Good afternoon' artinya 'selamat siang/sore'. 3. Jadi balas dengan 'Good afternoon' juga." },
    { q: "What do you say when you go home from school?", options: ["Good bye", "Good morning", "Welcome", "Thank you"], answer: 0, solution: "1. Saat berpisah atau pulang, kita mengucapkan salam perpisahan. 2. 'Good bye' artinya 'selamat tinggal'. 3. 'Good morning' untuk menyapa di pagi hari, bukan untuk perpisahan." },
    { q: "What number is 'twelve'?", options: ["10", "11", "12", "20"], answer: 2, solution: "1. 'Ten' = 10, 'eleven' = 11, 'twelve' = 12. 2. 'Twenty' = 20, jangan tertukar dengan 'twelve'. 3. Jadi 'twelve' adalah angka 12." },
    { q: "How do you write 15 in English?", options: ["fiveteen", "fifteen", "fifty", "fivety"], answer: 1, solution: "1. Angka 15 dalam bahasa Inggris adalah 'fifteen'. 2. Bentuknya tidak beraturan, bukan 'fiveteen'. 3. 'Fifty' artinya 50, jadi hati-hati tertukar." },
    { q: "What color do you get when you mix red and yellow?", options: ["green", "purple", "orange", "brown"], answer: 2, solution: "1. Merah dalam bahasa Inggris 'red', kuning 'yellow'. 2. Campuran merah dan kuning menghasilkan warna oranye. 3. Oranye dalam bahasa Inggris adalah 'orange'." },
    { q: "A fish lives in the ...", options: ["water", "tree", "sky", "cage"], answer: 0, solution: "1. 'Fish' artinya ikan. 2. Ikan bernapas dengan insang dan hidup di air. 3. Air dalam bahasa Inggris adalah 'water'." },
    { q: "My mother's sister is my ...", options: ["uncle", "aunt", "sister", "niece"], answer: 1, solution: "1. 'Mother's sister' artinya saudara perempuan ibu. 2. Saudara perempuan orang tua disebut bibi atau tante. 3. Bibi dalam bahasa Inggris adalah 'aunt'. 'Uncle' artinya paman." },
    { q: "We borrow books from the ...", options: ["canteen", "library", "garden", "office"], answer: 1, solution: "1. 'Borrow books' artinya meminjam buku. 2. Tempat meminjam dan membaca buku di sekolah adalah perpustakaan. 3. Perpustakaan dalam bahasa Inggris adalah 'library'." },
    { q: "'Penghapus' in English is ...", options: ["ruler", "eraser", "pencil", "sharpener"], answer: 1, solution: "1. 'Penghapus' dipakai untuk menghapus tulisan pensil. 2. Dalam bahasa Inggris disebut 'eraser'. 3. 'Ruler' artinya penggaris, 'sharpener' artinya rautan." },
    { q: "He ___ football on Sunday.", options: ["play", "plays", "playing", "played"], answer: 1, solution: "1. Ini kalimat simple present dengan subjek 'he'. 2. Untuk he/she/it, kata kerja ditambah -s atau -es. 3. Jadi 'play' menjadi 'plays'." },
    { q: "She ___ eat vegetables.", options: ["don't", "doesn't", "isn't", "not"], answer: 1, solution: "1. Ini kalimat negatif dalam simple present. 2. Subjek 'she' memakai 'doesn't'. 3. 'Don't' dipakai untuk I, you, we, dan they." },
    { q: "___ a cat under the table.", options: ["There is", "There are", "They are", "It are"], answer: 0, solution: "1. 'A cat' adalah satu ekor kucing (tunggal). 2. Untuk benda tunggal dipakai 'there is'. 3. 'There are' dipakai untuk benda jamak (banyak)." },
    { q: "___ many students in the class.", options: ["There is", "There are", "It is", "There was"], answer: 1, solution: "1. 'Many students' berarti banyak siswa (jamak). 2. Untuk benda jamak dipakai 'there are'. 3. Kalimat lengkapnya: 'There are many students in the class.'" },
    { q: "The book is ___ the table.", options: ["in", "on", "under", "at"], answer: 1, solution: "1. Buku terletak di atas meja (menempel pada permukaan). 2. Kata depan untuk 'di atas permukaan' adalah 'on'. 3. 'Under' artinya di bawah, 'in' artinya di dalam." },
    { q: "The cat is hiding ___ the box.", options: ["on", "in", "at", "to"], answer: 1, solution: "1. Kucing bersembunyi di dalam kotak. 2. Kata depan untuk 'di dalam' adalah 'in'. 3. 'On' artinya di atas, jadi tidak tepat." },
    { q: "___ are playing football. (the boys)", options: ["He", "She", "They", "It"], answer: 2, solution: "1. 'The boys' berarti anak-anak laki-laki (lebih dari satu). 2. Kata ganti untuk banyak orang adalah 'they'. 3. 'He' dan 'she' hanya untuk satu orang." },
    { q: "___ is a pen. (near me)", options: ["This", "That", "These", "Those"], answer: 0, solution: "1. 'This' dipakai untuk benda tunggal yang dekat dengan pembicara. 2. Karena penanya dekat ('near me'), pakai 'this'. 3. 'That' untuk benda yang jauh, 'these/those' untuk benda jamak." },
    { q: "What day comes after Friday?", options: ["Thursday", "Saturday", "Sunday", "Monday"], answer: 1, solution: "1. Urutan hari: ... Thursday, Friday, Saturday, Sunday. 2. Hari sesudah Friday (Jumat) adalah Saturday (Sabtu). 3. 'After' artinya 'sesudah'." },
    { q: "I brush my ___ every morning.", options: ["teeth", "tooth", "tooths", "teeths"], answer: 0, solution: "1. Bentuk jamak (plural) dari 'tooth' (gigi) tidak beraturan. 2. Bentuk jamaknya adalah 'teeth', bukan 'tooths'. 3. Karena menyikat semua gigi (banyak), pakai 'teeth'." },
    { q: "'Berlari' in English is ...", options: ["walk", "run", "jump", "swim"], answer: 1, solution: "1. 'Berlari' adalah bergerak cepat dengan kaki. 2. Dalam bahasa Inggris disebut 'run'. 3. 'Walk' artinya berjalan, 'jump' melompat, 'swim' berenang." },
    { q: "We see with our ___.", options: ["ears", "eyes", "nose", "feet"], answer: 1, solution: "1. 'See' artinya melihat. 2. Anggota tubuh yang dipakai untuk melihat adalah mata. 3. Mata dalam bahasa Inggris adalah 'eyes'." },
    { q: "We wear ___ on our feet when we go to school.", options: ["hats", "shoes", "gloves", "shirts"], answer: 1, solution: "1. 'Feet' artinya kaki. 2. Benda yang dipakai di kaki adalah sepatu. 3. Sepatu dalam bahasa Inggris adalah 'shoes'." },
    { q: "'Roti' in English is ...", options: ["rice", "bread", "milk", "egg"], answer: 1, solution: "1. 'Roti' adalah makanan yang dipanggang dari tepung. 2. Dalam bahasa Inggris disebut 'bread'. 3. 'Rice' artinya nasi, 'milk' artinya susu." },
    { q: "A person who helps sick people in the hospital is a ...", options: ["teacher", "doctor", "farmer", "driver"], answer: 1, solution: "1. 'Sick people' artinya orang-orang yang sakit. 2. Orang yang merawat orang sakit di rumah sakit adalah dokter. 3. Dokter dalam bahasa Inggris adalah 'doctor'." },
    { q: "I ___ at home yesterday.", options: ["am", "was", "are", "is"], answer: 1, solution: "1. 'Yesterday' artinya kemarin, jadi kalimatnya bentuk lampau (past). 2. Bentuk lampau dari 'am' adalah 'was'. 3. Kalimat lengkapnya: 'I was at home yesterday.'" },
    { q: "They ___ happy yesterday.", options: ["was", "were", "are", "is"], answer: 1, solution: "1. 'Yesterday' menandakan bentuk lampau. 2. Subjek 'they' (jamak) memakai 'were' dalam bentuk lampau. 3. 'Was' hanya dipakai untuk I, he, she, dan it." },
    { q: "She ___ to the market yesterday.", options: ["go", "goes", "went", "going"], answer: 2, solution: "1. 'Yesterday' menandakan kejadian lampau. 2. Bentuk lampau (past) dari 'go' adalah 'went'. 3. Kalimat lengkapnya: 'She went to the market yesterday.'" },
    { q: "We ___ rice this morning.", options: ["eat", "eats", "ate", "eating"], answer: 2, solution: "1. 'This morning' menunjukkan waktu yang sudah lewat. 2. Bentuk lampau dari 'eat' adalah 'ate'. 3. Kalimat lengkapnya: 'We ate rice this morning.'" },
    { q: "The clock shows 7.00. We say ...", options: ["seven o'clock", "half past seven", "seven past o'clock", "half seven"], answer: 0, solution: "1. Jam 7.00 tepat dibaca 'seven o'clock'. 2. 'O'clock' dipakai untuk jam yang tepat (pas). 3. 'Half past seven' artinya jam setengah delapan (7.30)." },
    { q: "The clock shows 7.30. We say ...", options: ["seven o'clock", "half past seven", "seven half", "thirty past seven"], answer: 1, solution: "1. Jam 7.30 dibaca 'half past seven'. 2. 'Half past' artinya 'setengah lewat' dari jam yang disebutkan. 3. Jadi 7.30 = setengah lewat tujuh = 'half past seven'." },
    { q: "The dog is sleeping ___ the table.", options: ["on", "in", "under", "at"], answer: 2, solution: "1. Anjing tidur di bawah meja. 2. Kata depan untuk 'di bawah' adalah 'under'. 3. 'On' artinya di atas, 'in' artinya di dalam." },
    { q: "The shop is ___ the school. (di sebelah)", options: ["between", "next to", "under", "behind"], answer: 1, solution: "1. Toko itu berada di sebelah sekolah. 2. Kata depan untuk 'di sebelah' adalah 'next to'. 3. 'Between' artinya di antara dua benda." },
    { q: "My house is ___ the bank and the post office.", options: ["between", "behind", "under", "on"], answer: 0, solution: "1. Rumahku berada di antara bank dan kantor pos. 2. Kata depan untuk 'di antara' adalah 'between'. 3. 'Between' dipakai untuk posisi di antara dua benda." },
    { q: "___ name is Rina. (I)", options: ["My", "Your", "His", "Her"], answer: 0, solution: "1. Kata sifat milik (possessive adjective) untuk 'I' adalah 'my'. 2. 'My name' artinya 'nama saya'. 3. 'Your' untuk kamu, 'his' untuk dia laki-laki." },
    { q: "He is my brother. ___ name is Andi.", options: ["My", "Your", "His", "Her"], answer: 2, solution: "1. Subjeknya 'he' (dia laki-laki). 2. Kata sifat milik untuk 'he' adalah 'his'. 3. Jadi kalimatnya: 'His name is Andi.'" },
    { q: "___ is a car. (far from me)", options: ["This", "That", "These", "Those"], answer: 1, solution: "1. 'That' dipakai untuk benda tunggal yang jauh dari pembicara. 2. Karena mobilnya jauh ('far from me'), pakai 'that'. 3. 'This' untuk benda yang dekat, 'these/those' untuk benda jamak." },
    { q: "A fish ___ climb a tree.", options: ["can", "can't", "is", "does"], answer: 1, solution: "1. 'Can' artinya 'dapat/bisa', sedangkan 'can't' artinya 'tidak dapat'. 2. Ikan tidak bisa memanjat pohon. 3. Jadi kalimat negatifnya: 'A fish can't climb a tree.'" },
    { q: "I like ___ football with my friends.", options: ["play", "playing", "plays", "played"], answer: 1, solution: "1. Setelah kata 'like' (suka), kata kerja memakai bentuk -ing. 2. Aturannya: like + verb-ing. 3. Jadi yang benar: 'I like playing football.'" },
    { q: "How many months are there in a year?", options: ["Ten", "Eleven", "Twelve", "Thirteen"], answer: 2, solution: "1. 'Year' artinya satu tahun. 2. Nama-nama bulannya: January, February, March, April, May, June, July, August, September, October, November, December. 3. Jumlahnya ada 12, dalam bahasa Inggris 'twelve'." },
    { q: "A: 'How are you?' B: '___'", options: ["I'm fine, thank you.", "Good morning.", "See you later.", "Good night."], answer: 0, solution: "1. 'How are you?' artinya 'Apa kabarmu?' 2. Jawaban yang tepat adalah tentang kabar, yaitu 'I'm fine, thank you.' 3. 'Good morning' adalah sapaan, bukan jawaban tentang kabar." },
    { q: "What animal says 'woof woof'?", options: ["duck", "dog", "goat", "lion"], answer: 1, solution: "1. Suara 'woof woof' adalah gonggongan anjing. 2. 'Dog' artinya anjing. 3. Jadi hewan yang bersuara 'woof woof' adalah 'dog'." },
    { q: "Which animal has feathers and can fly in the sky?", options: ["bird", "butterfly", "frog", "snake"], answer: 0, solution: "1. 'Feathers' artinya bulu. 2. Hewan yang memiliki bulu dan bisa terbang di langit adalah burung. 3. Jadi jawabannya adalah 'bird' yang artinya burung." },
    { q: "Which animal has long ears and likes to eat carrots?", options: ["goat", "sheep", "horse", "rabbit"], answer: 3, solution: "1. Hewan bertelinga panjang yang suka makan wortel adalah kelinci. 2. 'Rabbit' artinya kelinci. 3. Jadi jawabannya adalah 'rabbit'." },
    { q: "Which animal says 'quack quack' and can swim?", options: ["chicken", "cow", "duck", "goat"], answer: 2, solution: "1. Suara 'quack quack' adalah suara bebek, dan bebek bisa berenang. 2. 'Duck' artinya bebek. 3. Jadi jawabannya adalah 'duck'." },
    { q: "Which animal says 'cluck cluck' and lays eggs?", options: ["cow", "chicken", "goat", "horse"], answer: 1, solution: "1. Suara 'cluck cluck' adalah suara ayam, dan ayam bertelur. 2. 'Chicken' artinya ayam. 3. Jadi jawabannya adalah 'chicken'." },
    { q: "Which animal says 'moo' and gives us milk?", options: ["goat", "sheep", "horse", "cow"], answer: 3, solution: "1. Suara 'moo' adalah suara sapi, dan sapi menghasilkan susu. 2. 'Cow' artinya sapi. 3. Jadi jawabannya adalah 'cow'." },
    { q: "Which animal likes to climb rocks and eat grass?", options: ["goat", "cow", "horse", "sheep"], answer: 0, solution: "1. Hewan yang suka memanjat batu dan makan rumput adalah kambing. 2. 'Goat' artinya kambing. 3. Jadi jawabannya adalah 'goat'." },
    { q: "Which animal says 'neigh' and can carry people on its back?", options: ["cow", "sheep", "horse", "goat"], answer: 2, solution: "1. Suara 'neigh' adalah suara kuda, dan kuda bisa ditunggangi manusia. 2. 'Horse' artinya kuda. 3. Jadi jawabannya adalah 'horse'." },
    { q: "Which animal has thick, soft wool on its body?", options: ["goat", "sheep", "cow", "horse"], answer: 1, solution: "1. Hewan yang tubuhnya ditutupi wol yang tebal dan lembut adalah domba. 2. 'Sheep' artinya domba. 3. Jadi jawabannya adalah 'sheep'." },
    { q: "Which insect has beautiful colorful wings and comes from a caterpillar?", options: ["bee", "ant", "spider", "butterfly"], answer: 3, solution: "1. Serangga yang memiliki sayap indah berwarna-warni dan berasal dari ulat adalah kupu-kupu. 2. 'Butterfly' artinya kupu-kupu. 3. Jadi jawabannya adalah 'butterfly'." },
    { q: "Which insect makes honey?", options: ["ant", "spider", "bee", "butterfly"], answer: 2, solution: "1. Serangga yang membuat madu adalah lebah. 2. 'Bee' artinya lebah. 3. Jadi jawabannya adalah 'bee'." },
    { q: "Which animal says 'croak' and can jump very far?", options: ["frog", "rabbit", "monkey", "bird"], answer: 0, solution: "1. Suara 'croak' adalah suara katak, dan katak bisa melompat sangat jauh. 2. 'Frog' artinya katak. 3. Jadi jawabannya adalah 'frog'." },
    { q: "We wear a hat on our ___.", options: ["hand", "leg", "head", "arm"], answer: 2, solution: "1. Topi dipakai di kepala. 2. 'Head' artinya kepala. 3. Jadi jawabannya adalah 'head'." },
    { q: "We smell flowers with our ___.", options: ["mouth", "nose", "ear", "hand"], answer: 1, solution: "1. Kita mencium bau bunga dengan hidung. 2. 'Nose' artinya hidung. 3. Jadi jawabannya adalah 'nose'." },
    { q: "We eat and talk with our ___.", options: ["nose", "ear", "hand", "mouth"], answer: 3, solution: "1. Kita makan dan berbicara dengan mulut. 2. 'Mouth' artinya mulut. 3. Jadi jawabannya adalah 'mouth'." },
    { q: "We hear music with our ___.", options: ["ear", "nose", "mouth", "hand"], answer: 0, solution: "1. Kita mendengar musik dengan telinga. 2. 'Ear' artinya telinga. 3. Jadi jawabannya adalah 'ear'." },
    { q: "We hold a pencil with our ___.", options: ["arm", "leg", "hand", "foot"], answer: 2, solution: "1. Kita memegang pensil dengan tangan. 2. 'Hand' artinya tangan. 3. Jadi jawabannya adalah 'hand'." },
    { q: "A hand has five ___.", options: ["toes", "fingers", "arms", "legs"], answer: 1, solution: "1. Satu tangan memiliki lima jari. 2. 'Fingers' artinya jari-jari tangan. 3. Jadi jawabannya adalah 'fingers'." },
    { q: "We kick a ball with our ___.", options: ["arm", "hand", "foot", "leg"], answer: 3, solution: "1. Kita menendang bola dengan kaki. 2. 'Leg' artinya kaki. 3. Jadi jawabannya adalah 'leg'." },
    { q: "We wear shoes on our ___.", options: ["foot", "hand", "head", "arm"], answer: 0, solution: "1. Sepatu dipakai di kaki. 2. 'Foot' artinya kaki (telapak kaki). 3. Jadi jawabannya adalah 'foot'." },
    { q: "Indonesian people eat ___ every day.", options: ["bread", "rice", "cake", "candy"], answer: 1, solution: "1. Orang Indonesia makan nasi setiap hari. 2. 'Rice' artinya nasi. 3. Jadi jawabannya adalah 'rice'." },
    { q: "A baby drinks ___.", options: ["tea", "juice", "water", "milk"], answer: 3, solution: "1. Bayi minum susu. 2. 'Milk' artinya susu. 3. Jadi jawabannya adalah 'milk'." },
    { q: "We drink ___ when we are thirsty.", options: ["water", "milk", "tea", "juice"], answer: 0, solution: "1. Kita minum air saat haus. 2. 'Water' artinya air. 3. Jadi jawabannya adalah 'water'." },
    { q: "Sweet ___ is made from oranges.", options: ["milk", "tea", "juice", "water"], answer: 2, solution: "1. Minuman manis yang dibuat dari buah jeruk adalah jus. 2. 'Juice' artinya jus. 3. Jadi jawabannya adalah 'juice'." },
    { q: "Which fruit is red and round?", options: ["banana", "apple", "orange", "cake"], answer: 1, solution: "1. Buah yang berwarna merah dan berbentuk bulat adalah apel. 2. 'Apple' artinya apel. 3. Jadi jawabannya adalah 'apple'." },
    { q: "Which fruit is yellow and long?", options: ["apple", "orange", "cake", "banana"], answer: 3, solution: "1. Buah yang berwarna kuning dan berbentuk panjang adalah pisang. 2. 'Banana' artinya pisang. 3. Jadi jawabannya adalah 'banana'." },
    { q: "Which fruit has the same name as a color?", options: ["orange", "apple", "banana", "cake"], answer: 0, solution: "1. Buah yang namanya sama dengan nama warna adalah jeruk. 2. 'Orange' artinya jeruk (dan juga warna oranye). 3. Jadi jawabannya adalah 'orange'." },
    { q: "We eat ___ on birthdays.", options: ["bread", "candy", "cake", "rice"], answer: 2, solution: "1. Kita makan kue saat ulang tahun. 2. 'Cake' artinya kue. 3. Jadi jawabannya adalah 'cake'." },
    { q: "Chicken and beef are kinds of ___.", options: ["vegetable", "meat", "fruit", "cake"], answer: 1, solution: "1. Ayam dan daging sapi termasuk jenis daging. 2. 'Meat' artinya daging. 3. Jadi jawabannya adalah 'meat'." },
    { q: "Carrots and spinach are ___.", options: ["fruits", "meat", "candy", "vegetables"], answer: 3, solution: "1. Wortel dan bayam termasuk sayuran. 2. 'Vegetables' artinya sayur-sayuran. 3. Jadi jawabannya adalah 'vegetables'." },
    { q: "My mother's husband is my ___.", options: ["father", "mother", "brother", "sister"], answer: 0, solution: "1. Suami dari ibu adalah ayah. 2. 'Father' artinya ayah. 3. Jadi jawabannya adalah 'father'." },
    { q: "My father's wife is my ___.", options: ["father", "sister", "mother", "brother"], answer: 2, solution: "1. Istri dari ayah adalah ibu. 2. 'Mother' artinya ibu. 3. Jadi jawabannya adalah 'mother'." },
    { q: "My parents' son is my ___.", options: ["sister", "brother", "father", "son"], answer: 1, solution: "1. Anak laki-laki dari orang tuaku adalah saudara laki-lakiku. 2. 'Brother' artinya saudara laki-laki. 3. Jadi jawabannya adalah 'brother'." },
    { q: "My parents' daughter is my ___.", options: ["brother", "mother", "father", "sister"], answer: 3, solution: "1. Anak perempuan dari orang tuaku adalah saudara perempuanku. 2. 'Sister' artinya saudara perempuan. 3. Jadi jawabannya adalah 'sister'." },
    { q: "Mr. Budi has a boy. The boy is his ___.", options: ["son", "daughter", "brother", "father"], answer: 0, solution: "1. Anak laki-laki Pak Budi adalah putranya. 2. 'Son' artinya anak laki-laki (putra). 3. Jadi jawabannya adalah 'son'." },
    { q: "Mrs. Ani has a girl. The girl is her ___.", options: ["son", "mother", "daughter", "sister"], answer: 2, solution: "1. Anak perempuan Bu Ani adalah putrinya. 2. 'Daughter' artinya anak perempuan (putri). 3. Jadi jawabannya adalah 'daughter'." },
    { q: "A very young child is called a ___.", options: ["son", "baby", "daughter", "brother"], answer: 1, solution: "1. Anak yang masih sangat kecil disebut bayi. 2. 'Baby' artinya bayi. 3. Jadi jawabannya adalah 'baby'." },
    { q: "Father and mother are our ___.", options: ["brothers", "sisters", "children", "parents"], answer: 3, solution: "1. Ayah dan ibu adalah orang tua kita. 2. 'Parents' artinya orang tua. 3. Jadi jawabannya adalah 'parents'." },
    { q: "A ___ teaches students at school.", options: ["doctor", "teacher", "farmer", "driver"], answer: 1, solution: "1. Orang yang mengajar murid di sekolah adalah guru. 2. 'Teacher' artinya guru. 3. Jadi jawabannya adalah 'teacher'." },
    { q: "If you are sick, you go to see a ___.", options: ["doctor", "nurse", "teacher", "pilot"], answer: 0, solution: "1. Jika sakit, kita pergi ke dokter. 2. 'Doctor' artinya dokter. 3. Jadi jawabannya adalah 'doctor'." },
    { q: "A ___ grows rice in the fields.", options: ["fisherman", "driver", "cook", "farmer"], answer: 3, solution: "1. Orang yang menanam padi di sawah adalah petani. 2. 'Farmer' artinya petani. 3. Jadi jawabannya adalah 'farmer'." },
    { q: "A ___ drives a bus.", options: ["pilot", "police", "driver", "farmer"], answer: 2, solution: "1. Orang yang mengemudikan bus adalah sopir. 2. 'Driver' artinya sopir. 3. Jadi jawabannya adalah 'driver'." },
    { q: "A ___ flies an airplane.", options: ["pilot", "driver", "police", "teacher"], answer: 0, solution: "1. Orang yang menerbangkan pesawat adalah pilot. 2. 'Pilot' artinya pilot. 3. Jadi jawabannya adalah 'pilot'." },
    { q: "A ___ catches thieves.", options: ["soldier", "doctor", "police", "farmer"], answer: 2, solution: "1. Orang yang menangkap pencuri adalah polisi. 2. 'Police' artinya polisi. 3. Jadi jawabannya adalah 'police'." },
    { q: "A ___ helps the doctor in the hospital.", options: ["doctor", "nurse", "teacher", "singer"], answer: 1, solution: "1. Orang yang membantu dokter di rumah sakit adalah perawat. 2. 'Nurse' artinya perawat. 3. Jadi jawabannya adalah 'nurse'." },
    { q: "A ___ sings songs on the stage.", options: ["teacher", "cook", "tailor", "singer"], answer: 3, solution: "1. Orang yang menyanyikan lagu di atas panggung adalah penyanyi. 2. 'Singer' artinya penyanyi. 3. Jadi jawabannya adalah 'singer'." },
    { q: "The main cook in a restaurant is called a ___.", options: ["chef", "chief", "cook", "teacher"], answer: 0, solution: "1. Juru masak utama di restoran disebut koki kepala. 2. 'Chef' artinya koki kepala (jangan tertukar dengan 'chief' yang artinya ketua). 3. Jadi jawabannya adalah 'chef'." },
    { q: "A ___ fights to protect the country.", options: ["police", "pilot", "soldier", "farmer"], answer: 2, solution: "1. Orang yang berjuang melindungi negara adalah tentara. 2. 'Soldier' artinya tentara (prajurit). 3. Jadi jawabannya adalah 'soldier'." },
    { q: "A ___ makes and sews clothes.", options: ["sailor", "teacher", "farmer", "tailor"], answer: 3, solution: "1. Orang yang membuat dan menjahit pakaian adalah penjahit. 2. 'Tailor' artinya penjahit (jangan tertukar dengan 'sailor' yang artinya pelaut). 3. Jadi jawabannya adalah 'tailor'." },
    { q: "A ___ catches fish in the sea.", options: ["farmer", "fisherman", "sailor", "driver"], answer: 1, solution: "1. Orang yang menangkap ikan di laut adalah nelayan. 2. 'Fisherman' artinya nelayan. 3. Jadi jawabannya adalah 'fisherman'." },
    { q: "How do you spell the number 8 in English?", options: ["eigth", "eght", "eight", "eith"], answer: 2, solution: "1. Soal menanyakan ejaan angka 8 dalam bahasa Inggris. 2. Ejaan yang benar adalah 'eight'; 'eigth' adalah kesalahan umum yang menukar posisi i dan h. 3. Jadi jawaban yang benar adalah 'eight'." },
    { q: "How do you write 20 in English?", options: ["twenty", "twenti", "twentie", "twinty"], answer: 0, solution: "1. Soal menanyakan penulisan angka 20 dalam bahasa Inggris. 2. Penulisan yang benar adalah 'twenty', bukan 'twenti' atau 'twentie'. 3. Jadi jawaban yang benar adalah 'twenty'." },
    { q: "How do you write 40 in English?", options: ["fourty", "forty", "fourti", "forrty"], answer: 1, solution: "1. Soal menanyakan penulisan angka 40 dalam bahasa Inggris. 2. Penulisan yang benar adalah 'forty' tanpa huruf u; 'fourty' adalah kesalahan umum. 3. Jadi jawaban yang benar adalah 'forty'." },
    { q: "How do you spell the number 9 in English?", options: ["nain", "nign", "ninee", "nine"], answer: 3, solution: "1. Soal menanyakan ejaan angka 9 dalam bahasa Inggris. 2. Ejaan yang benar adalah 'nine'; 'nign' dan 'nain' adalah salah tulis. 3. Jadi jawaban yang benar adalah 'nine'." },
    { q: "What number is 'three'?", options: ["13", "3", "30", "33"], answer: 1, solution: "1. Soal menanyakan angka dari kata 'three'. 2. 'Three' berarti 3; jangan tertukar dengan 'thirty' (30) atau 'thirteen' (13). 3. Jadi 'three' adalah angka 3." },
    { q: "Andi wins the race. He is the ___ winner.", options: ["first", "one", "once", "oneth"], answer: 0, solution: "1. Andi memenangkan lomba, artinya ia juara ke-1. 2. Bilangan bertingkat (ordinal number) untuk urutan ke-1 adalah 'first', bukan 'one'. 3. Jadi kalimatnya: He is the first winner." },
    { q: "How do you write 100 in English?", options: ["one hunderd", "one hundreds", "one hundred", "a hunderd"], answer: 2, solution: "1. Soal menanyakan penulisan angka 100 dalam bahasa Inggris. 2. Penulisan yang benar adalah 'one hundred'; 'hunderd' adalah salah eja. 3. Jadi jawaban yang benar adalah 'one hundred'." },
    { q: "What number is 'fifty'?", options: ["15", "5", "55", "50"], answer: 3, solution: "1. Soal menanyakan angka dari kata 'fifty'. 2. 'Fifty' berarti 50; jangan tertukar dengan 'fifteen' yang berarti 15. 3. Jadi 'fifty' adalah angka 50." },
    { q: "Which is the correct spelling of 30?", options: ["thirti", "thirty", "thrity", "therty"], answer: 1, solution: "1. Soal menanyakan ejaan yang benar untuk angka 30. 2. Ejaan yang benar adalah 'thirty'; 'thrity' dan 'therty' salah. 3. Jadi jawaban yang benar adalah 'thirty'." },
    { q: "How do you write 60 in English?", options: ["sixti", "siksty", "sixty", "sixety"], answer: 2, solution: "1. Soal menanyakan penulisan angka 60 dalam bahasa Inggris. 2. Penulisan yang benar adalah 'sixty', bukan 'sixti' atau 'sixety'. 3. Jadi jawaban yang benar adalah 'sixty'." },
    { q: "Sinta finishes in second place. She is the ___ runner.", options: ["second", "two", "twice", "twond"], answer: 0, solution: "1. Sinta finis di posisi ke-2. 2. Bilangan bertingkat (ordinal number) untuk urutan ke-2 adalah 'second', bukan 'two'. 3. Jadi kalimatnya: She is the second runner." },
    { q: "Budi stands in line at number 3. He is the ___ person in line.", options: ["three", "threeth", "thrid", "third"], answer: 3, solution: "1. Budi berada di urutan ke-3 dalam antrean. 2. Bilangan bertingkat (ordinal number) untuk urutan ke-3 adalah 'third', bukan 'three' atau 'thrid'. 3. Jadi kalimatnya: He is the third person in line." },
    { q: "What color is the night sky?", options: ["white", "black", "gray", "blue"], answer: 1, solution: "1. Soal menanyakan warna langit pada malam hari. 2. Langit malam tampak gelap kehitaman. 3. Jadi jawabannya adalah 'black'." },
    { q: "Milk is ___.", options: ["white", "yellow", "pink", "gray"], answer: 0, solution: "1. Soal menanyakan warna susu. 2. Susu berwarna putih. 3. Jadi jawabannya adalah 'white'." },
    { q: "A flamingo is ___.", options: ["red", "purple", "pink", "white"], answer: 2, solution: "1. Soal menanyakan warna burung flamingo. 2. Flamingo terkenal dengan bulunya yang berwarna merah muda. 3. Jadi jawabannya adalah 'pink'." },
    { q: "Grapes are usually ___.", options: ["pink", "brown", "green", "purple"], answer: 3, solution: "1. Soal menanyakan warna buah anggur pada umumnya. 2. Anggur yang umum berwarna ungu. 3. Jadi jawabannya adalah 'purple'." },
    { q: "Chocolate is ___.", options: ["black", "brown", "gray", "white"], answer: 1, solution: "1. Soal menanyakan warna cokelat. 2. Cokelat (chocolate) berwarna cokelat. 3. Jadi jawabannya adalah 'brown'." },
    { q: "An elephant is ___.", options: ["gray", "black", "brown", "white"], answer: 0, solution: "1. Soal menanyakan warna gajah. 2. Kulit gajah berwarna abu-abu. 3. Jadi jawabannya adalah 'gray'." },
    { q: "What day comes after Wednesday?", options: ["Tuesday", "Monday", "Thursday", "Friday"], answer: 2, solution: "1. Urutan hari: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday. 2. Hari setelah Wednesday adalah Thursday. 3. Jadi jawabannya adalah Thursday." },
    { q: "What day comes before Sunday?", options: ["Saturday", "Monday", "Friday", "Thursday"], answer: 0, solution: "1. Urutan hari: ... Friday, Saturday, Sunday. 2. Hari sebelum Sunday adalah Saturday. 3. Jadi jawabannya adalah Saturday." },
    { q: "In Indonesia, the week usually starts on ___.", options: ["Sunday", "Saturday", "Friday", "Monday"], answer: 3, solution: "1. Di Indonesia, kalender biasanya memulai minggu pada hari Senin. 2. Hari Senin dalam bahasa Inggris adalah Monday. 3. Jadi jawabannya adalah Monday." },
    { q: "What is the last month of the year?", options: ["November", "December", "January", "October"], answer: 1, solution: "1. Urutan bulan: January ... November, December. 2. Bulan terakhir dalam setahun adalah bulan ke-12. 3. Jadi jawabannya adalah December." },
    { q: "What month comes after June?", options: ["May", "August", "July", "June"], answer: 2, solution: "1. Urutan bulan: ... May, June, July, August ... 2. Bulan setelah June adalah July. 3. Jadi jawabannya adalah July." },
    { q: "Indonesia's Independence Day (17 August) is in ___.", options: ["August", "June", "July", "September"], answer: 0, solution: "1. Hari Kemerdekaan Indonesia diperingati setiap tanggal 17 Agustus. 2. Agustus dalam bahasa Inggris adalah August. 3. Jadi jawabannya adalah August." },
    { q: "Kartini Day (Hari Kartini, 21 April) is in ___.", options: ["March", "April", "May", "June"], answer: 1, solution: "1. Hari Kartini diperingati setiap tanggal 21 April. 2. April dalam bahasa Inggris tetap April. 3. Jadi jawabannya adalah April." },
    { q: "What month comes before October?", options: ["November", "August", "December", "September"], answer: 3, solution: "1. Urutan bulan: ... August, September, October ... 2. Bulan sebelum October adalah September. 3. Jadi jawabannya adalah September." },
    { q: "In Indonesia, the dry season usually lasts from April to ___.", options: ["December", "February", "September", "November"], answer: 2, solution: "1. Di Indonesia ada dua musim: musim hujan (rainy season) dan musim kemarau (dry season). 2. Musim kemarau biasanya berlangsung dari April sampai September. 3. Jadi jawabannya adalah September." },
    { q: "Which season is usually the hottest?", options: ["winter", "summer", "spring", "autumn"], answer: 1, solution: "1. Ada empat musim: summer, winter, spring, autumn. 2. Musim yang paling panas adalah summer (musim panas). 3. Jadi jawabannya adalah summer." },
    { q: "In winter, the weather is usually ___.", options: ["cold", "hot", "warm", "sunny"], answer: 0, solution: "1. Winter adalah musim dingin. 2. Saat winter, cuaca biasanya dingin. 3. Dingin dalam bahasa Inggris adalah cold, jadi jawabannya adalah cold." },
    { q: "Flowers usually bloom in ___.", options: ["winter", "summer", "autumn", "spring"], answer: 3, solution: "1. Spring adalah musim semi. 2. Pada musim semi, bunga-bunga biasanya bermekaran. 3. Jadi jawabannya adalah spring." },
    { q: "The clock shows 3.00. We say 'It is ___.'", options: ["half past three", "three o'clock", "quarter past three", "three past o'clock"], answer: 1, solution: "1. Jam menunjukkan pukul 3.00 tepat. 2. Untuk jam yang tepat (pas), kita memakai ungkapan 'o'clock'. 3. Jadi kita berkata 'It is three o'clock'." },
    { q: "'It is half past four.' What time is it?", options: ["04.30", "04.15", "05.30", "03.30"], answer: 0, solution: "1. 'Half past four' artinya lewat setengah jam dari pukul empat. 2. Setengah jam setelah 04.00 adalah 04.30. 3. Jadi waktunya adalah 04.30." },
    { q: "'It is quarter past five.' What time is it?", options: ["05.45", "04.15", "05.15", "05.30"], answer: 2, solution: "1. 'Quarter past five' artinya lewat seperempat jam dari pukul lima. 2. Seperempat jam (15 menit) setelah 05.00 adalah 05.15. 3. Jadi waktunya adalah 05.15." },
    { q: "'It is quarter to nine.' What time is it?", options: ["09.15", "09.45", "08.15", "08.45"], answer: 3, solution: "1. 'Quarter to nine' artinya kurang seperempat jam menuju pukul sembilan. 2. 15 menit sebelum 09.00 adalah 08.45. 3. Jadi waktunya adalah 08.45." },
    { q: "The clock shows 10.15. We say 'It is ___.'", options: ["quarter to ten", "quarter past ten", "half past ten", "ten o'clock"], answer: 1, solution: "1. Jam menunjukkan 10.15. 2. 15 menit lewat dari jam 10 disebut 'quarter past ten'. 3. Jadi kita berkata 'It is quarter past ten'." },
    { q: "The clock shows 6.45. We say 'It is ___.'", options: ["quarter to seven", "quarter past six", "half past six", "quarter to six"], answer: 0, solution: "1. Jam menunjukkan 6.45. 2. 15 menit sebelum jam 7 disebut 'quarter to seven'. 3. Jadi kita berkata 'It is quarter to seven'." },
    { q: "'It is half past two.' What time is it?", options: ["02.15", "03.30", "02.30", "01.30"], answer: 2, solution: "1. 'Half past two' artinya lewat setengah jam dari pukul dua. 2. Setengah jam setelah 02.00 adalah 02.30. 3. Jadi waktunya adalah 02.30." },
    { q: "What do we say at 8.00?", options: ["eight half", "half eight", "o'clock eight", "eight o'clock"], answer: 3, solution: "1. Pukul 8.00 adalah jam yang tepat (pas). 2. Untuk jam tepat, ungkapan yang benar adalah 'eight o'clock'. 3. Jadi jawabannya adalah 'eight o'clock'." },
    { q: "'It is quarter to eleven.' What time is it?", options: ["11.15", "10.45", "11.45", "10.15"], answer: 1, solution: "1. 'Quarter to eleven' artinya kurang seperempat jam menuju pukul sebelas. 2. 15 menit sebelum 11.00 adalah 10.45. 3. Jadi waktunya adalah 10.45." },
    { q: "The clock shows 1.30. We say 'It is ___.'", options: ["half past one", "half past two", "one and half", "past half one"], answer: 0, solution: "1. Jam menunjukkan 1.30. 2. 30 menit lewat dari jam 1 disebut 'half past one'. 3. Jadi kita berkata 'It is half past one'." },
    { q: "What do you say to greet someone in the evening?", options: ["Good night", "Good afternoon", "Good evening", "Good morning"], answer: 2, solution: "1. Soal menanyakan sapaan untuk sore menjelang malam hari. 2. Sapaan yang tepat untuk waktu tersebut adalah 'Good evening'; 'Good night' dipakai saat akan tidur. 3. Jadi jawabannya adalah 'Good evening'." },
    { q: "What do you say to your mother before you go to sleep?", options: ["Good night", "Good evening", "Good morning", "See you"], answer: 0, solution: "1. Sebelum tidur, kita mengucapkan selamat malam. 2. 'Selamat malam' saat akan tidur dalam bahasa Inggris adalah 'Good night'. 3. Jadi jawabannya adalah 'Good night'." },
    { q: "Someone helps you carry your bag. You say '___'.", options: ["Sorry", "Thank you", "Excuse me", "Good bye"], answer: 1, solution: "1. Seseorang membantumu membawa tas. 2. Ungkapan terima kasih dalam bahasa Inggris adalah 'Thank you'. 3. Jadi kamu berkata 'Thank you'." },
    { q: "Your friend says 'Thank you'. You answer '___'.", options: ["I'm sorry", "See you", "Me too", "You're welcome"], answer: 3, solution: "1. Temanmu berkata 'Thank you'. 2. Jawaban yang tepat untuk 'Thank you' adalah 'You're welcome' (sama-sama). 3. Jadi jawabannya adalah 'You're welcome'." },
    { q: "You step on your friend's foot by accident. You say '___'.", options: ["Thank you", "Good night", "Sorry", "Excuse me"], answer: 2, solution: "1. Kamu tidak sengaja menginjak kaki temanmu. 2. Saat berbuat salah, kita meminta maaf dengan berkata 'Sorry'. 3. Jadi kamu berkata 'Sorry'." },
    { q: "Your friend says 'Sorry'. You answer '___'.", options: ["That's okay", "You're welcome", "Good evening", "Thank you"], answer: 0, solution: "1. Temanmu berkata 'Sorry' (minta maaf). 2. Jawaban yang tepat untuk permintaan maaf adalah 'That's okay' (tidak apa-apa). 3. Jadi jawabannya adalah 'That's okay'." },
    { q: "You want to ask a stranger a question politely. First you say '___'.", options: ["Sorry", "Excuse me", "Good night", "Hey you"], answer: 1, solution: "1. Kamu ingin bertanya kepada orang asing dengan sopan. 2. Sebelum bertanya, ucapkan dulu 'Excuse me' (permisi). 3. Jadi jawabannya adalah 'Excuse me'." },
    { q: "You will meet your friend again tomorrow. You say '___'.", options: ["Good night", "Good morning", "See you yesterday", "See you tomorrow"], answer: 3, solution: "1. Kamu akan bertemu temanmu lagi besok. 2. Ungkapan perpisahan 'sampai jumpa besok' dalam bahasa Inggris adalah 'See you tomorrow'. 3. Jadi kamu berkata 'See you tomorrow'." },
    { q: "You meet a new friend for the first time. You say '___'.", options: ["See you tomorrow", "I'm sorry", "Nice to meet you", "Good night"], answer: 2, solution: "1. Kamu bertemu teman baru untuk pertama kalinya. 2. Ungkapan yang tepat adalah 'Nice to meet you' (senang bertemu denganmu). 3. Jadi jawabannya adalah 'Nice to meet you'." },
    { q: "Which sentence is polite and correct?", options: ["I fine thank you.", "I'm fine, thank you.", "Me fine thank you.", "I am fine, thanks you."], answer: 1, solution: "1. Soal menanyakan kalimat yang sopan dan benar tata bahasanya. 2. Jawaban sopan untuk 'How are you?' adalah 'I'm fine, thank you.'; pilihan lain salah tata bahasa. 3. Jadi jawabannya adalah 'I'm fine, thank you.'" },
    { q: "We ___ ready for class now.", options: ["are", "is", "am", "be"], answer: 0, solution: "1. Aturannya: subjek 'we' (kami) selalu dipasangkan dengan 'are', bukan 'is' atau 'am'. 2. Kalimat ini memakai 'We', jadi bentuk yang tepat adalah 'are'. 3. Jadi kalimat lengkapnya: 'We are ready for class now.'" },
    { q: "She ___ my best friend.", options: ["am", "be", "is", "are"], answer: 2, solution: "1. Aturannya: 'she' (dia perempuan) dipasangkan dengan 'is'. 2. Kata 'be' adalah bentuk dasar dan tidak boleh dipakai langsung di sini. 3. Jadi jawabannya 'is': 'She is my best friend.'" },
    { q: "They ___ not tired after the game.", options: ["isn't", "aren't", "is", "am not"], answer: 1, solution: "1. Aturannya: untuk subjek jamak 'they', bentuk negatifnya adalah 'aren't' (are not), bukan 'isn't'. 2. Kalimat memakai 'They', jadi pilih 'aren't'. 3. Jadi kalimat lengkapnya: 'They aren't tired after the game.'" },
    { q: "___ he a doctor?", options: ["Are", "Be", "Am", "Is"], answer: 3, solution: "1. Aturannya: kalimat tanya dengan 'he' memakai 'Is' di depan kalimat. 2. Subjek kalimat ini adalah 'he', jadi kata pembukanya 'Is'. 3. Jadi kalimat lengkapnya: 'Is he a doctor?'" },
    { q: "You ___ very kind to your friends.", options: ["is", "are", "am", "be"], answer: 1, solution: "1. Aturannya: 'you' (kamu/kalian) selalu memakai 'are'. 2. Subjek di sini 'You', jadi bentuk yang benar adalah 'are'. 3. Jadi kalimat lengkapnya: 'You are very kind to your friends.'" },
    { q: "The children ___ playing in the park.", options: ["is", "am", "are", "be"], answer: 2, solution: "1. Aturannya: 'children' artinya anak-anak (jamak), jadi pasangannya 'are'. 2. Kata 'children' jamak, maka gunakan 'are'. 3. Jadi kalimat lengkapnya: 'The children are playing in the park.'" },
    { q: "I ___ hungry now.", options: ["are", "is", "am", "be"], answer: 2, solution: "1. Aturannya: 'I' (saya) selalu memakai 'am', tidak pernah 'is' atau 'are'. 2. Subjeknya 'I', jadi pilih 'am'. 3. Jadi kalimat lengkapnya: 'I am hungry now.'" },
    { q: "It ___ raining today.", options: ["are", "am", "be", "is"], answer: 3, solution: "1. Aturannya: 'it' dipasangkan dengan 'is'. 2. Subjeknya 'It', jadi pilih 'is'. 3. Jadi kalimat lengkapnya: 'It is raining today.'" },
    { q: "My father ___ a farmer.", options: ["are", "am", "is", "be"], answer: 2, solution: "1. Aturannya: 'my father' berarti 'he' (dia laki-laki) yang memakai 'is'. 2. 'My father' itu satu orang laki-laki, jadi pilih 'is'. 3. Jadi kalimat lengkapnya: 'My father is a farmer.'" },
    { q: "My parents ___ at home now.", options: ["is", "are", "am", "be"], answer: 1, solution: "1. Aturannya: 'my parents' berarti 'they' (mereka, jamak) yang memakai 'are'. 2. 'Parents' itu lebih dari satu orang, jadi pilih 'are'. 3. Jadi kalimat lengkapnya: 'My parents are at home now.'" },
    { q: "___ they your cousins?", options: ["Is", "Are", "Am", "Be"], answer: 1, solution: "1. Aturannya: kalimat tanya dengan 'they' memakai 'Are' di depan kalimat. 2. Subjeknya 'they', jadi kata pembukanya 'Are'. 3. Jadi kalimat lengkapnya: 'Are they your cousins?'" },
    { q: "___ you like chocolate?", options: ["Do", "Does", "Is", "Are"], answer: 0, solution: "1. Aturannya: kalimat tanya dengan 'you' memakai 'Do', sedangkan 'Does' hanya untuk he/she/it. 2. Subjeknya 'you', jadi pilih 'Do'. 3. Jadi kalimat lengkapnya: 'Do you like chocolate?'" },
    { q: "She ___ not like spicy food.", options: ["do", "are", "does", "is"], answer: 2, solution: "1. Aturannya: bentuk negatif untuk 'she' adalah 'does not' (doesn't), bukan 'do not'. 2. Subjeknya 'She', jadi pilih 'does'. 3. Jadi kalimat lengkapnya: 'She does not like spicy food.'" },
    { q: "___ he play the guitar?", options: ["Do", "Does", "Is", "Are"], answer: 1, solution: "1. Aturannya: kalimat tanya dengan 'he' memakai 'Does', lalu kata kerjanya tetap 'play' tanpa -s. 2. Subjeknya 'he', jadi pilih 'Does'. 3. Jadi kalimat lengkapnya: 'Does he play the guitar?'" },
    { q: "They ___ not watch TV at night.", options: ["doesn't", "don't", "isn't", "aren't"], answer: 1, solution: "1. Aturannya: bentuk negatif untuk 'they' adalah 'do not' (don't), bukan 'doesn't'. 2. Subjeknya 'They', jadi pilih 'don't'. 3. Jadi kalimat lengkapnya: 'They don't watch TV at night.'" },
    { q: "I ___ a new bicycle.", options: ["has", "haves", "have", "having"], answer: 2, solution: "1. Aturannya: 'I' memakai 'have', sedangkan 'has' hanya untuk he/she/it. 2. Subjeknya 'I', jadi pilih 'have'. 3. Jadi kalimat lengkapnya: 'I have a new bicycle.'" },
    { q: "She ___ two cats at home.", options: ["have", "has", "haves", "having"], answer: 1, solution: "1. Aturannya: 'she' memakai 'has'. Kata 'haves' tidak ada dalam bahasa Inggris. 2. Subjeknya 'She', jadi pilih 'has'. 3. Jadi kalimat lengkapnya: 'She has two cats at home.'" },
    { q: "___ we need umbrellas today?", options: ["Does", "Do", "Is", "Are"], answer: 1, solution: "1. Aturannya: kalimat tanya dengan 'we' memakai 'Do'. 2. Subjeknya 'we', jadi pilih 'Do'. 3. Jadi kalimat lengkapnya: 'Do we need umbrellas today?'" },
    { q: "My brother ___ not have a phone.", options: ["does", "do", "is", "are"], answer: 0, solution: "1. Aturannya: 'my brother' berarti 'he' yang memakai 'does not' (doesn't) dalam kalimat negatif. 2. Subjeknya 'My brother' (= he), jadi pilih 'does'. 3. Jadi kalimat lengkapnya: 'My brother does not have a phone.'" },
    { q: "Rina ___ long hair.", options: ["have", "haves", "having", "has"], answer: 3, solution: "1. Aturannya: nama satu orang perempuan seperti 'Rina' berarti 'she' yang memakai 'has'. 2. 'Rina' itu satu orang, jadi pilih 'has'. 3. Jadi kalimat lengkapnya: 'Rina has long hair.'" },
    { q: "Do they ___ in Jakarta?", options: ["lives", "live", "living", "life"], answer: 1, solution: "1. Aturannya: setelah 'Do' kata kerja harus bentuk dasar tanpa -s, jadi 'live' bukan 'lives'. 2. Subjek 'they' + 'Do', maka kata kerja tetap 'live'. 3. Jadi kalimat lengkapnya: 'Do they live in Jakarta?'" },
    { q: "I ___ sick last week.", options: ["was", "were", "am", "are"], answer: 0, solution: "1. Aturannya: dalam past tense, 'I' memakai 'was', bukan 'were'. 2. Ada kata 'last week' (waktu lampau), dan subjeknya 'I', jadi pilih 'was'. 3. Jadi kalimat lengkapnya: 'I was sick last week.'" },
    { q: "They ___ at the beach yesterday.", options: ["was", "were", "is", "are"], answer: 1, solution: "1. Aturannya: dalam past tense, 'they' memakai 'were'. 2. Ada kata 'yesterday', dan subjeknya 'They', jadi pilih 'were'. 3. Jadi kalimat lengkapnya: 'They were at the beach yesterday.'" },
    { q: "She ___ not at school yesterday.", options: ["isn't", "wasn't", "aren't", "weren't"], answer: 1, solution: "1. Aturannya: bentuk negatif past tense untuk 'she' adalah 'wasn't' (was not). 2. Ada kata 'yesterday', dan subjeknya 'She', jadi pilih 'wasn't'. 3. Jadi kalimat lengkapnya: 'She was not at school yesterday.'" },
    { q: "We ___ very happy last night.", options: ["was", "is", "were", "are"], answer: 2, solution: "1. Aturannya: dalam past tense, 'we' memakai 'were'. 2. Ada kata 'last night', dan subjeknya 'We', jadi pilih 'were'. 3. Jadi kalimat lengkapnya: 'We were very happy last night.'" },
    { q: "He ___ late this morning.", options: ["were", "was", "is", "are"], answer: 1, solution: "1. Aturannya: dalam past tense, 'he' memakai 'was'. 2. Subjeknya 'He' dan kejadiannya sudah lewat, jadi pilih 'was'. 3. Jadi kalimat lengkapnya: 'He was late this morning.'" },
    { q: "You ___ right about the answer.", options: ["was", "are", "is", "were"], answer: 3, solution: "1. Aturannya: dalam past tense, 'you' selalu memakai 'were', tidak pernah 'was'. 2. Subjeknya 'You', jadi pilih 'were'. 3. Jadi kalimat lengkapnya: 'You were right about the answer.'" },
    { q: "The weather ___ cold yesterday.", options: ["were", "is", "was", "are"], answer: 2, solution: "1. Aturannya: 'the weather' berarti 'it' yang dalam past tense memakai 'was'. 2. Ada kata 'yesterday', jadi pilih 'was'. 3. Jadi kalimat lengkapnya: 'The weather was cold yesterday.'" },
    { q: "My friends ___ not here an hour ago.", options: ["wasn't", "isn't", "aren't", "weren't"], answer: 3, solution: "1. Aturannya: bentuk negatif past tense untuk 'my friends' (= they, jamak) adalah 'weren't'. 2. 'Friends' itu jamak, jadi pilih 'weren't'. 3. Jadi kalimat lengkapnya: 'My friends weren't here an hour ago.'" },
    { q: "We ___ football yesterday afternoon.", options: ["played", "play", "plays", "playing"], answer: 0, solution: "1. Aturannya: kata kerja beraturan dalam past tense ditambah -ed: play → played. 2. Ada kata 'yesterday', jadi pakai 'played'. 3. Jadi kalimat lengkapnya: 'We played football yesterday afternoon.'" },
    { q: "She ___ for the test last night.", options: ["study", "studied", "studies", "studying"], answer: 1, solution: "1. Aturannya: 'study' berubah jadi 'studied' (y → ied) dalam past tense. 2. Ada kata 'last night', jadi pakai 'studied'. 3. Jadi kalimat lengkapnya: 'She studied for the test last night.'" },
    { q: "They ___ a movie last Sunday.", options: ["watch", "watched", "watches", "watching"], answer: 1, solution: "1. Aturannya: 'watch' dalam past tense ditambah -ed menjadi 'watched'. 2. Ada kata 'last Sunday', jadi pakai 'watched'. 3. Jadi kalimat lengkapnya: 'They watched a movie last Sunday.'" },
    { q: "I ___ to my grandma's house yesterday.", options: ["go", "goes", "went", "going"], answer: 2, solution: "1. Aturannya: 'go' adalah kata kerja tak beraturan, bentuk past-nya 'went' (bukan 'goed'). 2. Ada kata 'yesterday', jadi pakai 'went'. 3. Jadi kalimat lengkapnya: 'I went to my grandma's house yesterday.'" },
    { q: "He ___ fried rice for breakfast.", options: ["eat", "eats", "ate", "eating"], answer: 2, solution: "1. Aturannya: 'eat' tak beraturan, bentuk past-nya 'ate' (bukan 'eated'). 2. Sarapan ini sudah terjadi, jadi pakai 'ate'. 3. Jadi kalimat lengkapnya: 'He ate fried rice for breakfast.'" },
    { q: "We ___ a rainbow after the rain.", options: ["saw", "see", "sees", "seeing"], answer: 0, solution: "1. Aturannya: 'see' tak beraturan, bentuk past-nya 'saw'. 2. Kejadian sudah lewat, jadi pakai 'saw'. 3. Jadi kalimat lengkapnya: 'We saw a rainbow after the rain.'" },
    { q: "The baby ___ milk this morning.", options: ["drink", "drinks", "drank", "drinking"], answer: 2, solution: "1. Aturannya: 'drink' tak beraturan, bentuk past-nya 'drank' (bukan 'drinked'). 2. 'This morning' sudah lewat, jadi pakai 'drank'. 3. Jadi kalimat lengkapnya: 'The baby drank milk this morning.'" },
    { q: "She ___ a letter to her friend.", options: ["wrote", "write", "writes", "writing"], answer: 0, solution: "1. Aturannya: 'write' tak beraturan, bentuk past-nya 'wrote' (bukan 'writed'). 2. Kejadian sudah lewat, jadi pakai 'wrote'. 3. Jadi kalimat lengkapnya: 'She wrote a letter to her friend.'" },
    { q: "My father ___ a new car last month.", options: ["buy", "buys", "bought", "buying"], answer: 2, solution: "1. Aturannya: 'buy' tak beraturan, bentuk past-nya 'bought' (bukan 'buyed'). 2. Ada kata 'last month', jadi pakai 'bought'. 3. Jadi kalimat lengkapnya: 'My father bought a new car last month.'" },
    { q: "Doni ___ to school early yesterday.", options: ["came", "come", "comes", "coming"], answer: 0, solution: "1. Aturannya: 'come' tak beraturan, bentuk past-nya 'came'. 2. Ada kata 'yesterday', jadi pakai 'came'. 3. Jadi kalimat lengkapnya: 'Doni came to school early yesterday.'" },
    { q: "The dog ___ after the cat.", options: ["run", "runs", "running", "ran"], answer: 3, solution: "1. Aturannya: 'run' tak beraturan, bentuk past-nya 'ran' (bukan 'runned'). 2. Kejadian sudah lewat, jadi pakai 'ran'. 3. Jadi kalimat lengkapnya: 'The dog ran after the cat.'" },
    { q: "I ___ ride a bicycle.", options: ["can", "cans", "am can", "is can"], answer: 0, solution: "1. Aturannya: 'can' tidak pernah ditambah -s dan tidak perlu 'am/is' di depannya. 2. Subjeknya 'I', jadi cukup pakai 'can'. 3. Jadi kalimat lengkapnya: 'I can ride a bicycle.'" },
    { q: "She ___ speak English well.", options: ["cans", "can", "is can", "can to"], answer: 1, solution: "1. Aturannya: 'can' tetap sama untuk semua subjek, termasuk 'she' — tidak menjadi 'cans'. 2. Subjeknya 'She', jadi pakai 'can'. 3. Jadi kalimat lengkapnya: 'She can speak English well.'" },
    { q: "Fish ___ swim, but they ___ fly.", options: ["can / can", "cans / can't", "can / can't", "can't / can"], answer: 2, solution: "1. Aturannya: ikan bisa berenang (can swim) tetapi tidak bisa terbang (can't fly). 2. Bentuk yang benar: 'can' untuk kemampuan dan 'can't' untuk ketidakmampuan. 3. Jadi kalimat lengkapnya: 'Fish can swim, but they can't fly.'" },
    { q: "He ___ play football, and he ___ play chess too.", options: ["can / can't", "can / can", "cans / can", "can't / can't"], answer: 1, solution: "1. Aturannya: 'can' untuk dua kemampuan yang dimiliki, tanpa -s walau subjeknya 'he'. 2. Dia bisa keduanya, jadi pakai 'can' dua kali. 3. Jadi kalimat lengkapnya: 'He can play football, and he can play chess too.'" },
    { q: "Birds ___ fly in the sky.", options: ["cans", "is can", "can to", "can"], answer: 3, solution: "1. Aturannya: 'can' langsung diikuti kata kerja tanpa 'to' dan tanpa -s. 2. Burung bisa terbang, jadi pilih 'can'. 3. Jadi kalimat lengkapnya: 'Birds can fly in the sky.'" },
    { q: "A baby ___ walk alone.", options: ["can", "can't", "cans", "cans not"], answer: 1, solution: "1. Aturannya: bayi belum bisa berjalan sendiri, jadi bentuk negatifnya 'can't' (cannot). 2. Ini ketidakmampuan, jadi pilih 'can't'. 3. Jadi kalimat lengkapnya: 'A baby can't walk alone.'" },
    { q: "___ is my pencil. (near me)", options: ["This", "That", "These", "Those"], answer: 0, solution: "1. Aturannya: 'this' dipakai untuk satu benda yang dekat, diikuti 'is'. 2. Pensilnya satu dan dekat, jadi pilih 'This'. 3. Jadi kalimat lengkapnya: 'This is my pencil.'" },
    { q: "___ are my shoes. (near me)", options: ["This", "That", "These", "Those"], answer: 2, solution: "1. Aturannya: 'these' dipakai untuk benda jamak yang dekat, diikuti 'are'. 2. Sepatu itu jamak (sepasang) dan dekat, jadi pilih 'These'. 3. Jadi kalimat lengkapnya: 'These are my shoes.'" },
    { q: "___ is a tall tree over there. (far from me)", options: ["This", "That", "These", "Those"], answer: 1, solution: "1. Aturannya: 'that' dipakai untuk satu benda yang jauh, diikuti 'is'. 2. Pohonnya satu dan jauh ('over there'), jadi pilih 'That'. 3. Jadi kalimat lengkapnya: 'That is a tall tree over there.'" },
    { q: "Look! ___ birds are flying high. (far from me)", options: ["This", "That", "These", "Those"], answer: 3, solution: "1. Aturannya: 'those' dipakai untuk benda jamak yang jauh, diikuti 'are'. 2. Burung-burung itu jamak dan jauh, jadi pilih 'Those'. 3. Jadi kalimat lengkapnya: 'Look! Those birds are flying high.'" },
    { q: "The ball is ___ the chair.", options: ["under", "on", "in", "behind"], answer: 0, solution: "1. Kalimat berarti 'Bola itu ___ kursi'. 2. Bola berada di bawah kursi, jadi preposisi yang tepat adalah 'under' yang artinya 'di bawah'. 3. 'on' berarti di atas dan 'in' berarti di dalam, keduanya tidak sesuai dengan posisi bola." },
    { q: "The school is ___ the mosque.", options: ["in", "under", "on", "next to"], answer: 3, solution: "1. Kalimat berarti 'Sekolah itu ___ masjid'. 2. Sekolah terletak di sebelah masjid, jadi preposisi yang tepat adalah 'next to' yang artinya 'di sebelah'. 3. 'in' berarti di dalam, 'under' berarti di bawah, dan 'on' berarti di atas — semuanya salah untuk menyatakan posisi bersebelahan." },
    { q: "The cat is sleeping ___ the door.", options: ["on", "behind", "under", "in"], answer: 1, solution: "1. Kalimat berarti 'Kucing itu tidur ___ pintu'. 2. Kucing bersembunyi dan tidur di belakang pintu, jadi preposisi yang tepat adalah 'behind' yang artinya 'di belakang'. 3. 'on' berarti di atas dan 'under' berarti di bawah — tidak cocok karena kucingnya di balik pintu, bukan di atas atau di bawahnya." },
    { q: "The flowers are ___ the vase.", options: ["on", "behind", "in", "under"], answer: 2, solution: "1. Kalimat berarti 'Bunga-bunga itu ___ vas'. 2. Bunga ditaruh di dalam vas, jadi preposisi yang tepat adalah 'in' yang artinya 'di dalam'. 3. 'on' berarti di atas dan 'under' berarti di bawah — keduanya salah karena bunganya berada di dalam vas." },
    { q: "The boy is standing ___ the teacher.", options: ["in front of", "under", "between", "on"], answer: 0, solution: "1. Kalimat berarti 'Anak laki-laki itu berdiri ___ guru'. 2. Ia berdiri di depan guru, jadi frasa yang tepat adalah 'in front of' yang artinya 'di depan'. 3. 'under' berarti di bawah dan 'between' berarti di antara (butuh dua benda) — keduanya tidak sesuai." },
    { q: "The shoes are ___ the bed.", options: ["on", "in", "under", "next to"], answer: 2, solution: "1. Kalimat berarti 'Sepatu-sepatu itu ___ tempat tidur'. 2. Sepatu ditaruh di bawah tempat tidur, jadi preposisi yang tepat adalah 'under' yang artinya 'di bawah'. 3. 'on' berarti di atas dan 'next to' berarti di sebelah — tidak sesuai dengan posisi sepatu yang di kolong tempat tidur." },
    { q: "My house is ___ the park and the hospital.", options: ["next to", "between", "in front of", "under"], answer: 1, solution: "1. Kalimat berarti 'Rumahku ___ taman dan rumah sakit'. 2. Rumah berada di antara dua tempat (taman dan rumah sakit), jadi preposisi yang tepat adalah 'between' yang artinya 'di antara'. 3. 'between' dipakai untuk posisi di antara dua benda, sedangkan 'next to' hanya untuk satu benda di sebelahnya." },
    { q: "The bird is sitting ___ the branch.", options: ["under", "behind", "in", "on"], answer: 3, solution: "1. Kalimat berarti 'Burung itu hinggap ___ ranting'. 2. Burung hinggap di atas ranting, jadi preposisi yang tepat adalah 'on' yang artinya 'di atas'. 3. 'under' berarti di bawah dan 'in' berarti di dalam — tidak sesuai karena burungnya bertengger di atas ranting." },
    { q: "The keys are ___ my bag.", options: ["on", "in", "behind", "under"], answer: 1, solution: "1. Kalimat berarti 'Kunci-kunci itu ___ tasku'. 2. Kunci berada di dalam tas, jadi preposisi yang tepat adalah 'in' yang artinya 'di dalam'. 3. 'on' berarti di atas dan 'behind' berarti di belakang — salah karena kuncinya ada di dalam tas, bukan di atasnya." },
    { q: "The dog is waiting ___ the car.", options: ["on", "in front of", "behind", "under"], answer: 2, solution: "1. Kalimat berarti 'Anjing itu menunggu ___ mobil'. 2. Anjing menunggu di belakang mobil, jadi preposisi yang tepat adalah 'behind' yang artinya 'di belakang'. 3. 'in front of' berarti di depan dan 'under' berarti di bawah — keduanya tidak sesuai dengan posisi anjing." },
    { q: "The picture is ___ the wall.", options: ["on", "in", "under", "between"], answer: 0, solution: "1. Kalimat berarti 'Gambar itu ___ dinding'. 2. Gambar ditempel di dinding, jadi preposisi yang tepat adalah 'on' yang artinya 'di atas/menempel pada'. 3. 'in' berarti di dalam dan 'under' berarti di bawah — tidak cocok untuk gambar yang ditempel pada dinding." },
    { q: "Sinta is sitting ___ Budi and Dedi.", options: ["behind", "next to", "on", "between"], answer: 3, solution: "1. Kalimat berarti 'Sinta duduk ___ Budi dan Dedi'. 2. Sinta duduk di antara dua orang (Budi dan Dedi), jadi preposisi yang tepat adalah 'between' yang artinya 'di antara'. 3. 'between' dipakai saat posisinya diapit oleh dua benda atau orang." },
    { q: "A: Excuse me, Sir. May I go to the toilet?\nB: Yes, you may.\nWhat does the student ask permission for?", options: ["To go to the toilet", "To go home", "To go to the canteen", "To go to the library"], answer: 0, solution: "1. Murid bertanya 'May I go to the toilet?' yang artinya 'Bolehkah saya pergi ke toilet?'. 2. Guru menjawab 'Yes, you may' (Ya, boleh). 3. Jadi izin yang diminta adalah pergi ke toilet, bukan pulang atau ke kantin." },
    { q: "A: Can I borrow your pencil, please?\nB: Sure, here you are.\nWhat does A borrow from B?", options: ["A book", "A ruler", "A pencil", "An eraser"], answer: 2, solution: "1. A berkata 'Can I borrow your pencil, please?' yang artinya 'Bolehkah aku meminjam pensilmu?'. 2. B menjawab 'Sure, here you are' (Tentu, ini dia). 3. Jadi benda yang dipinjam adalah pensil (pencil), bukan buku atau penggaris." },
    { q: "A: Mom, where is my school bag?\nB: It is under the chair in the living room.\nWhere is the school bag?", options: ["On the table", "In the box", "Behind the door", "Under the chair"], answer: 3, solution: "1. A bertanya 'where is my school bag?' (di mana tas sekolahku?). 2. Ibu menjawab 'It is under the chair' (tasnya di bawah kursi). 3. Jadi tas sekolah ada di bawah kursi (under the chair)." },
    { q: "A: I would like a bowl of meatballs, please.\nB: That is ten thousand rupiah.\nWhat does A buy?", options: ["Fried rice", "Meatballs", "Orange juice", "Bread"], answer: 1, solution: "1. A berkata 'I would like a bowl of meatballs' yang artinya 'Saya mau semangkuk bakso'. 2. Kata 'meatballs' berarti bakso. 3. Jadi yang dibeli A adalah bakso, bukan nasi goreng atau jus jeruk." },
    { q: "A: Excuse me, where is the library?\nB: Go straight. It is next to the classroom.\nWhere is the library?", options: ["Next to the classroom", "Behind the school", "In front of the mosque", "Under the tree"], answer: 0, solution: "1. A bertanya 'where is the library?' (di mana perpustakaan?). 2. B menjawab 'It is next to the classroom' (di sebelah ruang kelas). 3. Jadi perpustakaan terletak di sebelah ruang kelas (next to the classroom)." },
    { q: "A: Hello, my name is Rani. What is your name?\nB: I am Dimas. Nice to meet you.\nWho introduces herself first?", options: ["Dimas", "The teacher", "Rani", "Nobody"], answer: 2, solution: "1. A membuka percakapan dengan 'my name is Rani' (namaku Rani) — ia memperkenalkan diri lebih dulu. 2. B baru memperkenalkan diri setelahnya ('I am Dimas'). 3. Jadi yang memperkenalkan diri pertama kali adalah Rani." },
    { q: "A: Can I borrow this storybook?\nB: Yes, but please return it tomorrow.\nWhen must A return the book?", options: ["Today", "Next week", "Next month", "Tomorrow"], answer: 3, solution: "1. A meminjam buku cerita. 2. B mengizinkan dengan syarat 'return it tomorrow' (kembalikan besok). 3. Jadi A harus mengembalikan buku itu besok (tomorrow)." },
    { q: "A: Budi, please help me carry this basket.\nB: Okay, Mom.\nWhat does Mom ask Budi to do?", options: ["Cook the rice", "Wash the dishes", "Carry the basket", "Clean the room"], answer: 2, solution: "1. Ibu berkata 'please help me carry this basket' (tolong bantu ibu membawa keranjang ini). 2. Kata 'carry' berarti membawa/mengangkat. 3. Jadi ibu meminta Budi membawakan keranjang (carry the basket)." },
    { q: "A: How much is the orange juice?\nB: It is five thousand rupiah.\nHow much is the orange juice?", options: ["Three thousand rupiah", "Five thousand rupiah", "Seven thousand rupiah", "Ten thousand rupiah"], answer: 1, solution: "1. A bertanya 'How much is the orange juice?' (berapa harga jus jeruk?). 2. B menjawab 'It is five thousand rupiah' (harganya lima ribu rupiah). 3. Jadi harga jus jeruk adalah lima ribu rupiah." },
    { q: "A: Excuse me, where is the toilet?\nB: It is behind the office.\nWhere is the toilet?", options: ["Next to the canteen", "In front of the class", "Under the stairs", "Behind the office"], answer: 3, solution: "1. A bertanya 'where is the toilet?' (di mana toilet?). 2. B menjawab 'It is behind the office' (di belakang kantor). 3. Jadi toilet terletak di belakang kantor (behind the office)." },
    { q: "A: This is my friend, Sinta. She is from Bandung.\nB: Hello, Sinta. Nice to meet you.\nWhere is Sinta from?", options: ["Jakarta", "Bandung", "Surabaya", "Medan"], answer: 1, solution: "1. A memperkenalkan temannya: 'She is from Bandung' (dia berasal dari Bandung). 2. Kata 'from' menunjukkan asal. 3. Jadi Sinta berasal dari Bandung." },
    { q: "A: May I drink some water, Mom?\nB: Of course, dear.\nWhat does the child ask permission for?", options: ["To eat some cake", "To play outside", "To drink some water", "To watch TV"], answer: 2, solution: "1. Anak bertanya 'May I drink some water?' (bolehkah aku minum air?). 2. Ibu menjawab 'Of course' (tentu saja). 3. Jadi izin yang diminta adalah minum air (drink some water)." },
    { q: "A: Have you had breakfast, Dinda?\nB: Yes, Dad. I had fried rice.\nWhat did Dinda have for breakfast?", options: ["Fried rice", "Bread", "Noodles", "Porridge"], answer: 0, solution: "1. Ayah bertanya 'Have you had breakfast?' (sudah sarapan?). 2. Dinda menjawab 'I had fried rice' (aku makan nasi goreng). 3. Jadi sarapan Dinda adalah nasi goreng (fried rice)." },
    { q: "A: Do you have an eraser? May I borrow it?\nB: Sorry, I do not have one.\nDoes B lend the eraser to A?", options: ["Yes, he lends it", "Yes, he buys a new one", "No, it is broken", "No, he does not have one"], answer: 3, solution: "1. A bertanya apakah B punya penghapus dan boleh meminjamnya. 2. B menjawab 'Sorry, I do not have one' (maaf, aku tidak punya). 3. Karena B tidak punya penghapus, ia tidak bisa meminjamkannya — jawabannya 'No, he does not have one'." },
    { q: "A: Excuse me, where is the nearest mosque?\nB: Turn left at the corner. It is in front of the park.\nWhere is the mosque?", options: ["Behind the market", "In front of the park", "Next to the school", "Between the shops"], answer: 1, solution: "1. A bertanya di mana masjid terdekat. 2. B menjawab 'It is in front of the park' (di depan taman). 3. Jadi masjid terletak di depan taman (in front of the park)." },
    { q: "A: Two iced teas, please.\nB: Here you are. Anything else?\nA: No, thank you.\nHow many iced teas does A buy?", options: ["One", "Three", "Two", "Four"], answer: 2, solution: "1. A memesan 'Two iced teas' (dua es teh). 2. Kata 'two' berarti dua. 3. Jadi A membeli dua gelas es teh (two)." },
    { q: "___ an apple on the plate.", options: ["There is", "There are", "There am", "They is"], answer: 0, solution: "1. 'an apple' adalah benda tunggal (satu apel). 2. Untuk benda tunggal, pola yang benar adalah 'There is' (ada). 3. 'There are' dipakai untuk benda jamak, jadi salah; 'There am' dan 'They is' bukan pola yang benar." },
    { q: "___ two books on the desk.", options: ["There are", "There is", "Is there", "There be"], answer: 0, solution: "1. 'two books' adalah benda jamak (dua buku). 2. Untuk benda jamak, pola yang benar adalah 'There are' (ada). 3. 'There is' hanya untuk benda tunggal, jadi salah di sini." },
    { q: "___ a cat in the garden?", options: ["Are there", "There are", "Is there", "There is"], answer: 2, solution: "1. Ini kalimat tanya tentang 'a cat' (seekor kucing, tunggal). 2. Untuk bertanya tentang benda tunggal, polanya adalah 'Is there ...?' (apakah ada ...?). 3. 'Are there' dipakai untuk benda jamak, sedangkan 'There is' bukan bentuk tanya." },
    { q: "___ any pens in your bag?", options: ["There is", "Is there", "There are", "Are there"], answer: 3, solution: "1. Ini kalimat tanya tentang 'pens' (pulpen-pulpen, jamak). 2. Untuk bertanya tentang benda jamak, polanya adalah 'Are there ...?' (apakah ada ...?). 3. 'Is there' hanya untuk benda tunggal, jadi salah di sini." },
    { q: "There ___ a television in my room.", options: ["aren't", "isn't", "am not", "don't"], answer: 1, solution: "1. 'a television' adalah benda tunggal. 2. Bentuk negatif dari 'There is' adalah 'There isn't' (tidak ada). 3. 'aren't' dipakai untuk benda jamak, sedangkan 'am not' dan 'don't' bukan pasangan dari 'there'." },
    { q: "There ___ five ducks in the pond.", options: ["is", "are", "am", "was"], answer: 1, solution: "1. 'five ducks' adalah benda jamak (lima bebek). 2. Untuk benda jamak, kata kerja yang benar adalah 'are', sehingga menjadi 'There are'. 3. 'is' hanya untuk benda tunggal, jadi salah di sini." },
    { q: "This is Budi. ___ likes playing chess.", options: ["He", "She", "They", "It"], answer: 0, solution: "1. Budi adalah anak laki-laki (satu orang). 2. Kata ganti untuk satu anak laki-laki adalah 'He' (dia). 3. 'She' untuk perempuan dan 'They' untuk jamak, jadi keduanya salah." },
    { q: "Sinta is my sister. ___ is a nurse.", options: ["He", "She", "It", "They"], answer: 1, solution: "1. Sinta adalah perempuan (satu orang). 2. Kata ganti untuk satu perempuan adalah 'She' (dia). 3. 'He' untuk laki-laki dan 'It' untuk benda, jadi keduanya salah." },
    { q: "The dog is hungry. Give ___ some food.", options: ["him", "it", "her", "them"], answer: 1, solution: "1. 'The dog' adalah seekor hewan (bukan manusia). 2. Kata ganti objek untuk hewan atau benda adalah 'it'. 3. 'him' dan 'her' dipakai untuk manusia, jadi salah di sini." },
    { q: "We live in Jakarta. ___ house is big.", options: ["Our", "Their", "My", "Your"], answer: 0, solution: "1. Subjeknya 'We' (kami). 2. Kata sifat milik untuk 'we' adalah 'our' (rumah kami). 3. 'My' untuk 'I' dan 'Their' untuk 'they', jadi keduanya salah di sini." },
    { q: "They are my friends. ___ names are Ali and Umar.", options: ["Their", "His", "Her", "Our"], answer: 0, solution: "1. Subjeknya 'They' (mereka). 2. Kata sifat milik untuk 'they' adalah 'their' (nama-nama mereka). 3. 'His' untuk satu laki-laki dan 'Her' untuk satu perempuan, jadi salah karena subjeknya jamak." },
    { q: "You are a good student. ___ bag is new.", options: ["My", "Your", "His", "Her"], answer: 1, solution: "1. Subjeknya 'You' (kamu). 2. Kata sifat milik untuk 'you' adalah 'your' (tasmu). 3. 'My' berarti milikku dan 'His' milik dia (laki-laki), jadi keduanya salah." }
  ]
};
